package com.mittiandmore.controller;
import com.mittiandmore.dto.*;import com.mittiandmore.service.DiscountService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/admin/discounts") public class AdminDiscountController {private final DiscountService service;public AdminDiscountController(DiscountService s){service=s;}@GetMapping public ResponseEntity<List<DiscountResponse>> all(){return ResponseEntity.ok(service.all());}@PostMapping public ResponseEntity<DiscountResponse> create(@Valid @RequestBody DiscountRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@PutMapping("/{id}") public ResponseEntity<DiscountResponse> update(@PathVariable Long id,@Valid @RequestBody DiscountRequest r){return ResponseEntity.ok(service.update(id,r));}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}}
